import{_ as e,o as a,c as i,a2 as n}from"./chunks/framework.KobcctIO.js";const u=JSON.parse(`{"title":"Verrous Atomiques et Sécurité d'Intégrité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/horizon/locks-and-security.md","filePath":"fr/guide/horizon/locks-and-security.md"}`),t={name:"fr/guide/horizon/locks-and-security.md"};function l(r,s,o,p,c,d){return a(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="verrous-atomiques-et-securite-d-integrite" tabindex="-1">Verrous Atomiques et Sécurité d&#39;Intégrité <a class="header-anchor" href="#verrous-atomiques-et-securite-d-integrite" aria-label="Permalink to &quot;Verrous Atomiques et Sécurité d&#39;Intégrité&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Verrouillage-Atomique%20%2B%20Heartbeat-blue.svg" alt="Verrouillage"><img src="https://img.shields.io/badge/S%C3%A9curit%C3%A9-Anti--Zip%20Slip-green.svg" alt="Anti-Zip Slip"><img src="https://img.shields.io/badge/Restauration-Rollback%20D%C3%A9terministe-orange.svg" alt="Restauration"></div><p>Dans un écosystème où plusieurs machines peuvent tenter d&#39;accéder au même profil Minecraft sur le cloud, la prévention de la corruption de données et l&#39;intégrité des archives décompressées constituent une priorité absolue.</p><hr><h2 id="_1-protocole-de-verrouillage-atomique-lock-js" tabindex="-1">1. Protocole de Verrouillage Atomique (<code>lock.js</code>) <a class="header-anchor" href="#_1-protocole-de-verrouillage-atomique-lock-js" aria-label="Permalink to &quot;1. Protocole de Verrouillage Atomique (\`lock.js\`)&quot;">​</a></h2><p>Pour empêcher que deux instances de synchronisation ne s&#39;exécutent simultanément sur le même dossier de jeu, Gens-Horizon applique un mécanisme de verrouillage physique strict :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Début de Synchronisation ]</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>    Tentative de création :</span></span>
<span class="line"><span>    fs.open(&#39;horizon.lock&#39;, O_CREAT | O_EXCL)</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>       +------+------+</span></span>
<span class="line"><span>       |             |</span></span>
<span class="line"><span>   [ SUCCÈS ]    [ ÉCHEC (EEXIST) ]</span></span>
<span class="line"><span>       |             |</span></span>
<span class="line"><span>       |             v</span></span>
<span class="line"><span>       |    Inspection du Verrou Existant :</span></span>
<span class="line"><span>       |    - Le PID maître est-il encore en vie ? (kill(pid, 0))</span></span>
<span class="line"><span>       |    - Le verrou date-t-il de plus de 2 heures ? (STALE_LOCK_MS)</span></span>
<span class="line"><span>       |             |</span></span>
<span class="line"><span>       |      +------+------+</span></span>
<span class="line"><span>       |      |             |</span></span>
<span class="line"><span>       |  [ ACTIF ]   [ ORPHELIN / MORT ]</span></span>
<span class="line"><span>       |      |             |</span></span>
<span class="line"><span>       |   Abus de          v</span></span>
<span class="line"><span>       |   conflit    Purge du verrou</span></span>
<span class="line"><span>       |  (Arrêt)     &amp; Recréation</span></span>
<span class="line"><span>       |                    |</span></span>
<span class="line"><span>       +--------------------+</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>[ Boucle Heartbeat toutes les 5 secondes ]</span></span>
<span class="line"><span>fs.promises.utimes(&#39;horizon.lock&#39;)</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>[ Fin de synchronisation : Suppression de horizon.lock ]</span></span></code></pre></div><h3 id="le-battement-de-cœur-heartbeat-5s" tabindex="-1">Le Battement de Cœur (Heartbeat 5s) <a class="header-anchor" href="#le-battement-de-cœur-heartbeat-5s" aria-label="Permalink to &quot;Le Battement de Cœur (Heartbeat 5s)&quot;">​</a></h3><p>Pendant toute la durée de la synchronisation (balayage, compression, téléversement), le processus maître met à jour la date de modification (<code>mtimeMs</code>) du fichier <code>horizon.lock</code> toutes les 5 secondes.</p><h3 id="detection-des-verrous-orphelins-stale-locks" tabindex="-1">Détection des Verrous Orphelins (Stale Locks) <a class="header-anchor" href="#detection-des-verrous-orphelins-stale-locks" aria-label="Permalink to &quot;Détection des Verrous Orphelins (Stale Locks)&quot;">​</a></h3><p>Si l&#39;ordinateur s&#39;éteint brutalement ou si le processus Node.js est tué (<code>SIGKILL</code>), le fichier <code>horizon.lock</code> persiste sur le disque. Au prochain lancement, Gens-Horizon inspecte le verrou :</p><ol><li><strong>Test d&#39;activité du PID (<code>process.kill(pid, 0)</code>) :</strong> Si le système d&#39;exploitation confirme que le PID n&#39;existe plus (<code>ESRCH</code>), le verrou est déclaré orphelin et purgé immédiatement.</li><li><strong>Seuil d&#39;inactivité (2 heures) :</strong> Même si le PID a été réaffecté par l&#39;OS, un verrou dont le heartbeat date de plus de 2 heures (<code>STALE_LOCK_MS = 7200000</code>) est automatiquement invalidé.</li></ol><h3 id="couplage-avec-le-lanceur-ipc-horizon-js" tabindex="-1">Couplage avec le Lanceur (<code>ipc-horizon.js</code>) <a class="header-anchor" href="#couplage-avec-le-lanceur-ipc-horizon-js" aria-label="Permalink to &quot;Couplage avec le Lanceur (\`ipc-horizon.js\`)&quot;">​</a></h3><p>Le Main Process de Gens-Launcher lit également le <code>mtimeMs</code> de <code>horizon.lock</code> avant d&#39;autoriser une action cloud depuis l&#39;interface utilisateur. La cohérence des constantes (intervalle de 5s et seuil de 2h) est strictement maintenue entre les deux dépôts.</p><hr><h2 id="_2-decompression-securisee-et-protection-anti-zip-slip-zip-utils-js" tabindex="-1">2. Décompression Sécurisée et Protection Anti-Zip Slip (<code>zip-utils.js</code>) <a class="header-anchor" href="#_2-decompression-securisee-et-protection-anti-zip-slip-zip-utils-js" aria-label="Permalink to &quot;2. Décompression Sécurisée et Protection Anti-Zip Slip (\`zip-utils.js\`)&quot;">​</a></h2><p>L&#39;extraction d&#39;archives ZIP distantes présente des risques majeurs si une archive malveillante contient des chemins relatifs piégés (ex: <code>../../../../Windows/System32</code>). Gens-Horizon neutralise cette menace :</p><ol><li><strong>Validation Mathématique du Chemin d&#39;Extraction :</strong><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> resolvedTarget</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(destDir);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> resolvedDest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(destDir, entry.fileName);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resolvedDest.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">startsWith</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(resolvedTarget </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path.sep) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolvedDest </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolvedTarget) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`Violation de sécurité Zip Slip : \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">entry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fileName</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>Contrôle de Signature Binaire :</strong> Avant toute décompression, le moteur vérifie que le fichier commence bien par le marqueur magique ZIP <code>0x504B0304</code> (<code>PK\\x03\\x04</code>) et que le répertoire central (<em>Central Directory</em>) est lisible.</li><li><strong>Moteur <code>yauzl</code> :</strong> L&#39;extraction utilise <code>yauzl</code> pour traiter les flux d&#39;entrée en continu sans charger l&#39;intégralité du fichier ZIP en mémoire vive, évitant les crashs sur des modpacks volumineux.</li></ol><hr><h2 id="_3-restauration-deterministe-d-historique-rollback-js" tabindex="-1">3. Restauration Déterministe d&#39;Historique (<code>rollback.js</code>) <a class="header-anchor" href="#_3-restauration-deterministe-d-historique-rollback-js" aria-label="Permalink to &quot;3. Restauration Déterministe d&#39;Historique (\`rollback.js\`)&quot;">​</a></h2><p>En cas de problème en jeu, Gens-Horizon permet de remonter dans le temps :</p><ul><li>Chaque session de synchronisation crée un instantané identifié par son timestamp et son empreinte de manifeste.</li><li>La commande <code>--rollback --instance &quot;Nom&quot; --target &quot;&lt;timestamp&gt;&quot;</code> reconstruit l&#39;arborescence exacte de l&#39;instance telle qu&#39;elle existait à ce point précis, en rejouant ou en annulant chronologiquement les deltas nécessaires.</li></ul>`,22)])])}const k=e(t,[["render",l]]);export{u as __pageData,k as default};
